<script setup lang="ts">
type ReportFilters={periodStart:string;periodEnd:string;grouping:'day'|'week'|'month';marketplace:string;product:string;category:string;channel:string}
const filters=defineModel<ReportFilters>('filters',{required:true});const {products,orders,expenses}=useAppData()
const parseDate=(value:unknown)=>{const text=String(value||'');if(/^\d{2}\/\d{2}\/\d{4}$/.test(text)){const [day,month,year]=text.split('/').map(Number);return new Date(year,month-1,day)}const date=new Date(text);return Number.isNaN(date.getTime())?null:date}
const inPeriod=(value:unknown)=>{const date=parseDate(value);return Boolean(date&&date>=new Date(`${filters.value.periodStart}T00:00:00`)&&date<=new Date(`${filters.value.periodEnd}T23:59:59`))}
const filteredOrders=computed(()=>orders.value.filter(order=>inPeriod(order.date)&&(filters.value.marketplace==='Todos'||(order.marketplace||'Sem marketplace')===filters.value.marketplace)&&(filters.value.product==='Todos'||order.product===filters.value.product)&&(filters.value.channel==='Todos'||(filters.value.channel==='Diretas'?order.salesChannel==='direct':order.salesChannel==='marketplace'))))
const filteredExpenses=computed(()=>expenses.value.filter(expense=>inPeriod(expense.date)&&(filters.value.category==='Todos'||expense.category===filters.value.category)))
const revenueTotal=computed(()=>filteredOrders.value.reduce((sum,item)=>sum+Number(item.gross||0),0));const feeTotal=computed(()=>filteredOrders.value.reduce((sum,item)=>sum+Number(item.fee||0),0));const shippingTotal=computed(()=>filteredOrders.value.reduce((sum,item)=>sum+Number(item.shipping||0),0));const costTotal=computed(()=>filteredOrders.value.reduce((sum,item)=>{const product=products.value.find(candidate=>String(candidate.id||'')===String(item.productId||'')||candidate.name===item.product);return sum+Number(product?.cost||0)*Number(item.qty||0)},0));const expenseTotal=computed(()=>filteredExpenses.value.reduce((sum,item)=>sum+Number(item.value||0),0));const netTotal=computed(()=>filteredOrders.value.reduce((sum,item)=>sum+Number(item.net||0),0));const profitTotal=computed(()=>filteredOrders.value.reduce((sum,item)=>sum+Number(item.profit||0),0)-expenseTotal.value);const margin=computed(()=>revenueTotal.value?profitTotal.value/revenueTotal.value*100:0);const ticket=computed(()=>filteredOrders.value.length?revenueTotal.value/filteredOrders.value.length:0)
const periodKey=(value:unknown)=>{const date=parseDate(value);if(!date)return'';if(filters.value.grouping==='day')return date.toISOString().slice(0,10);if(filters.value.grouping==='week')return`${date.toISOString().slice(0,7)}-S${Math.ceil(date.getDate()/7)}`;return date.toISOString().slice(0,7)}
const chartRows=computed(()=>{const rows=new Map<string,{revenue:number;net:number;expenses:number;profit:number}>();for(const order of filteredOrders.value){const key=periodKey(order.date);const row=rows.get(key)||{revenue:0,net:0,expenses:0,profit:0};row.revenue+=Number(order.gross||0);row.net+=Number(order.net||0);row.profit+=Number(order.profit||0);rows.set(key,row)}for(const expense of filteredExpenses.value){const key=periodKey(expense.date);const row=rows.get(key)||{revenue:0,net:0,expenses:0,profit:0};row.expenses+=Number(expense.value||0);row.profit-=Number(expense.value||0);rows.set(key,row)}return[...rows.entries()]});const chartLabels=computed(()=>chartRows.value.map(([key])=>key));const revenueChart=computed(()=>chartRows.value.map(([,row])=>row.revenue/1000));const expenseChart=computed(()=>chartRows.value.map(([,row])=>row.expenses/1000));const profitChart=computed(()=>chartRows.value.map(([,row])=>row.profit/1000));const marketplaceOptions=computed(()=>['Todos',...new Set(orders.value.map(item=>item.marketplace||'Sem marketplace'))]);const productOptions=computed(()=>['Todos',...new Set(products.value.map(item=>item.name))]);const categoryOptions=computed(()=>['Todos',...new Set(expenses.value.map(item=>item.category))])
const marketplaceBars=computed(()=>{const totals=new Map<string,number>();for(const order of filteredOrders.value)totals.set(order.marketplace||'Sem marketplace',(totals.get(order.marketplace||'Sem marketplace')||0)+Number(order.gross||0));const rows=[...totals.entries()].sort((a,b)=>b[1]-a[1]);const max=rows[0]?.[1]||0;return rows.map(([name,value])=>({name,value,percent:max?value/max*100:0}))});const expenseSegments=computed(()=>{const totals=new Map<string,number>();for(const expense of filteredExpenses.value)totals.set(expense.category||'Outros',(totals.get(expense.category||'Outros')||0)+Number(expense.value||0));return[...totals.entries()].map(([label,total])=>({label,total}))})
</script>
<template><div><div class="filters"><div class="field"><label>Início</label><input v-model="filters.periodStart" type="date"></div><div class="field"><label>Fim</label><input v-model="filters.periodEnd" type="date"></div><div class="field"><label>Agrupamento</label><select v-model="filters.grouping"><option value="month">Mensal</option><option value="week">Semanal</option><option value="day">Diário</option></select></div><div class="field"><label>Marketplace</label><select v-model="filters.marketplace"><option v-for="item in marketplaceOptions" :key="item">{{item}}</option></select></div><div class="field"><label>Canal de venda</label><select v-model="filters.channel"><option>Todos</option><option>Diretas</option><option>Marketplace</option></select></div><div class="field"><label>Produto</label><select v-model="filters.product"><option v-for="item in productOptions" :key="item">{{item}}</option></select></div><div class="field"><label>Categoria de despesa</label><select v-model="filters.category"><option v-for="item in categoryOptions" :key="item">{{item}}</option></select></div></div><div class="metrics-grid metrics-grid--5"><MetricCard label="Faturamento bruto" :value="formatCurrency(revenueTotal)" icon="trend" note="Período filtrado" :points="revenueChart"/><MetricCard label="Receita líquida" :value="formatCurrency(netTotal)" icon="wallet" note="Após taxas e frete" color="cyan" :points="chartRows.map(([,row])=>row.net/1000)"/><MetricCard label="Custos e despesas" :value="formatCurrency(costTotal+expenseTotal)" icon="money" note="Produção + operação" color="orange" :points="expenseChart"/><MetricCard label="Lucro líquido" :value="formatCurrency(profitTotal)" icon="chart" note="Resultado do período" :color="profitTotal>=0?'green':'red'" :points="profitChart"/><MetricCard label="Margem líquida" :value="`${margin.toFixed(1)}%`" icon="percent" note="Lucro / faturamento" color="purple" :points="chartRows.map(([,row])=>row.revenue?row.profit/row.revenue*100:0)"/></div><div class="dashboard-grid" style="grid-template-columns:1fr 1fr 1fr 1fr"><PanelCard title="Faturamento"><LineChart :values="revenueChart" :labels="chartLabels"/></PanelCard><PanelCard title="Taxas e frete"><LineChart :values="filteredOrders.map(x=>(Number(x.fee||0)+Number(x.shipping||0))/1000)" :labels="filteredOrders.map(x=>periodKey(x.date))" color="#f5a623"/></PanelCard><PanelCard title="Receita x despesas"><LineChart :values="revenueChart" :second="expenseChart" :labels="chartLabels"/></PanelCard><PanelCard title="Lucro líquido"><LineChart :values="profitChart" :labels="chartLabels" color="#0da566"/></PanelCard></div><div class="dashboard-grid" style="grid-template-columns:1fr 1fr 1fr 1fr"><PanelCard title="Composição financeira"><div class="report-breakdown"><div><span>Taxas ML</span><strong>{{formatCurrency(feeTotal)}}</strong></div><div><span>Frete</span><strong>{{formatCurrency(shippingTotal)}}</strong></div><div><span>Custo de produção</span><strong>{{formatCurrency(costTotal)}}</strong></div><div><span>Despesas operacionais</span><strong>{{formatCurrency(expenseTotal)}}</strong></div><div><span>Ticket médio</span><strong>{{formatCurrency(ticket)}}</strong></div></div></PanelCard><PanelCard title="Despesas por categoria"><DonutChart :segments="expenseSegments" :total="formatCurrency(expenseTotal)"/></PanelCard><PanelCard title="Faturamento por marketplace"><div class="bar-list" style="padding:20px"><div v-if="!marketplaceBars.length" class="empty-state">Nenhuma venda no período</div><div v-for="item in marketplaceBars" :key="item.name" class="bar-row"><span>{{item.name}}</span><div class="bar-row__track"><div class="bar-row__fill" :style="{width:`${item.percent}%`,background:'#1768f2'}"/></div><strong>{{formatCurrency(item.value)}}</strong></div></div></PanelCard><PanelCard title="Indicadores"><div class="report-breakdown"><div><span>Pedidos</span><strong>{{formatNumber(filteredOrders.length)}}</strong></div><div><span>Itens vendidos</span><strong>{{formatNumber(filteredOrders.reduce((sum,item)=>sum+Number(item.qty||0),0))}}</strong></div><div><span>Produtos ativos</span><strong>{{formatNumber(products.length)}}</strong></div><div><span>Período</span><strong>{{filters.periodStart}} a {{filters.periodEnd}}</strong></div></div></PanelCard></div></div></template>
<style scoped>.report-breakdown{display:grid;gap:12px;padding:18px}.report-breakdown div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #edf0f5;padding-bottom:8px}.report-breakdown span{color:#687386}.report-breakdown strong{color:#172033;text-align:right}</style>
